print('PASS: study schema required/types/enums/constants/additional-properties; protocol and evidence IDs; standalone artifacts/configs/hashes; four distinct variants and knowledge assessments.')
print('No training or tensor execution performed. Host validator reference unavailable in registry; no host acceptance claimed.')
for v in p['variants']:print(v['name'],v['role'],v['file'])
